link.script:
  document.addEventListener("DOMContentLoaded", function () {
    const scrollableContainers = document.querySelectorAll('.scrollable-container');

    if (window.innerWidth > 1024) {
      scrollableContainers.forEach(container => {
        let isMouseDown = false;
        let startX;
        let scrollStartPosition;
        let requestId;
        let momentum = 0;
        const friction = 0.92;

        container.addEventListener('mousedown', startDrag);
        container.addEventListener('mousemove', drag);
        document.addEventListener('mouseup', endDrag);
        container.addEventListener('mouseleave', endDrag);

        function startDrag(e) {
          e.preventDefault();
          isMouseDown = true;
          container.classList.add('active-scrolling');
          startX = e.pageX;
          scrollStartPosition = container.scrollLeft;
          cancelAnimationFrame(requestId);
        }

        function drag(e) {
          if (!isMouseDown) return;
          e.preventDefault();
          const x = e.pageX;
          const distance = x - startX;
          momentum = distance * 0.1;
          container.scrollLeft = scrollStartPosition - distance;
        }

        function endDrag() {
          if (!isMouseDown) return;
          isMouseDown = false;
          container.classList.remove('active-scrolling');
          animateMomentum();
        }

        function animateMomentum() {
          if (Math.abs(momentum) < 0.1) return;
          container.scrollLeft -= momentum;
          momentum *= friction;
          requestId = requestAnimationFrame(animateMomentum);
        }
      });
    } else {
      // Mobile/tablet: just remove 'active-scrolling' class if it somehow exists
      scrollableContainers.forEach(container => {
        container.classList.remove('active-scrolling');
      });
    }

    // Also listen for window resizing (optional, cleaner UX)
    window.addEventListener('resize', function() {
      if (window.innerWidth <= 1024) {
        scrollableContainers.forEach(container => {
          container.classList.remove('active-scrolling');
        });
      }
    });
  });

document.addEventListener("click", function (event) {
  const body = document.body;
  const toggleButton = document.querySelector('.menu-toggle');
//   const navMenu = document.querySelector('.main-header-bar-navigation');
const navMenu = document.querySelector('#ast-mobile-header');

  if (!toggleButton || !navMenu) return;

  const isMenuOpen = toggleButton.classList.contains('toggled');
  const clickedInsideMenu = navMenu.contains(event.target);
  const clickedToggle = toggleButton.contains(event.target);

  if (isMenuOpen && !clickedInsideMenu && !clickedToggle) {
    toggleButton.click(); // Let Astra handle closing
  }
});

body.script:
document.addEventListener('wpcf7mailsent', function(event) {
    if (!event.detail || !event.detail.inputs) return; // Prevent errors if inputs are missing

    var formId = event.detail.contactFormId; // Get the form ID
    var formData = event.detail.inputs;
    var email = '';
    var fullName = ''; // Changed from 'name' to avoid conflicts

    // Extract email and name values from the form
    formData.forEach(function(field) {
        if (field.name === 'your-email') {
            email = encodeURIComponent(field.value.trim());
        }
        if (field.name === 'your-name') {
            fullName = encodeURIComponent(field.value.trim());
        }
    });

    // Ensure proper URL formatting
    var queryParams = new URLSearchParams({ email: email, fullName: fullName }).toString();
    var redirectUrl = "/thank-you/?" + queryParams;

    // Redirect to the Thank You page
    window.location.href = redirectUrl;
}, false);

document.addEventListener("DOMContentLoaded", function () {

    const wrapper = document.querySelector(".custom-slider-wrapper");
    const container = wrapper?.querySelector(".scrollable-container");

    if (!wrapper || !container) return;

    /* =========================
       CREATE ARROWS
    ========================= */
    const leftArrow = document.createElement("div");
    leftArrow.className = "slider-arrow left";
    leftArrow.innerHTML = "❮";

    const rightArrow = document.createElement("div");
    rightArrow.className = "slider-arrow right";
    rightArrow.innerHTML = "❯";

    wrapper.appendChild(leftArrow);
    wrapper.appendChild(rightArrow);

    /* =========================
       GET SCROLL DISTANCE
    ========================= */
    function getScrollAmount() {
        const item = container.querySelector(".scroll-item");
        return item ? item.offsetWidth + 16 : 300;
    }

    /* =========================
       CUSTOM SMOOTH SCROLL
    ========================= */
    function smoothScroll(container, distance, duration = 200) {
        const start = container.scrollLeft;
        const startTime = performance.now();

        function animation(currentTime) {
            const timeElapsed = currentTime - startTime;
            const progress = Math.min(timeElapsed / duration, 1);

            // easeInOut animation
            const ease = progress < 0.5
                ? 2 * progress * progress
                : 1 - Math.pow(-2 * progress + 2, 2) / 2;

            container.scrollLeft = start + distance * ease;

            if (timeElapsed < duration) {
                requestAnimationFrame(animation);
            }
        }

        requestAnimationFrame(animation);
    }

    /* =========================
       ARROW CLICK EVENTS
    ========================= */
    leftArrow.addEventListener("click", () => {
        smoothScroll(container, -getScrollAmount(), 300); // adjust speed here
    });

    rightArrow.addEventListener("click", () => {
        smoothScroll(container, getScrollAmount(), 300); // adjust speed here
    });

});

function getClarityUserId() {
    const match = document.cookie.match(/_clck=([^;]+)/);
    if (!match) return null;

    const decoded = decodeURIComponent(match[1]);
    return decoded.split('^')[0];
}

function setClarityIdForAllForms() {
    const clarityId = getClarityUserId();
    const inputs = document.querySelectorAll('input[name="clarity_id"]');

    if (!clarityId || inputs.length === 0) return false;

    inputs.forEach(input => {
        input.value = clarityId;
    });

    return true;
}

function waitForFormsAndSetClarity(retries = 10) {
    if (!setClarityIdForAllForms() && retries > 0) {
        setTimeout(() => waitForFormsAndSetClarity(retries - 1), 500);
    }
}

document.addEventListener("DOMContentLoaded", () => {
    waitForFormsAndSetClarity();
});

document.addEventListener("wpcf7init", () => {
    waitForFormsAndSetClarity();
});

const observer = new MutationObserver(() => {
    if (setClarityIdForAllForms()) {
        observer.disconnect();
    }
});

observer.observe(document.body, {
    childList: true,
    subtree: true
});

/* =========================================================
   GLOBAL CF7 MULTI-CLICK PROTECTION
   Works on ALL CF7 forms automatically
========================================================= */

(function () {

  /* =====================================================
     BLOCK MULTIPLE CLICKS
  ===================================================== */
  document.addEventListener("click", function (e) {

    const submitBtn = e.target.closest(
      '.wpcf7-submit, input[type="submit"], button[type="submit"]'
    );

    if (!submitBtn) return;

    const form = submitBtn.closest("form");

    if (!form) return;


    /* ================= ALREADY SUBMITTING ================= */

    if (
      form.classList.contains("submitting") ||
      form.dataset.submitting === "true"
    ) {

      e.preventDefault();

      e.stopPropagation();

      e.stopImmediatePropagation();

      return false;

    }

  }, true);


  /* =====================================================
     DISABLE BUTTON ON SUBMIT
  ===================================================== */
  document.addEventListener(
    "wpcf7beforesubmit",
    function (event) {

      const form = event.target;

      if (!form) return;

      form.dataset.submitting = "true";

      const submitBtn = form.querySelector(
        '.wpcf7-submit, input[type="submit"], button[type="submit"]'
      );

      if (!submitBtn) return;

      submitBtn.disabled = true;

    },
    false
  );


  /* =====================================================
     ENABLE BUTTON AFTER RESPONSE
  ===================================================== */
  document.addEventListener(
    "wpcf7submit",
    function (event) {

      const form = event.target;

      if (!form) return;

      form.dataset.submitting = "false";

      const submitBtn = form.querySelector(
        '.wpcf7-submit, input[type="submit"], button[type="submit"]'
      );

      if (!submitBtn) return;

      submitBtn.disabled = false;

    },
    false
  );

})();

document.addEventListener("DOMContentLoaded", function () {
    const url = new URL(window.location.href);

    // Don't redirect this specific property
    const excludedPages = [
        "/properties/4927-heatherglen-dr-houston/"
    ];

    if (
        url.searchParams.get("virtualtour") === "true" &&
        !excludedPages.includes(url.pathname)
    ) {
        // Preserve UTM parameters
        url.searchParams.delete("virtualtour");

        window.location.replace(
            "https://novelsignaturehomes.com/vr-tour-private-request/" +
            (url.searchParams.toString() ? "?" + url.searchParams.toString() : "")
        );
    }
});

